'use client'

import * as React from 'react'

import { Button } from '@/components/ui/button'

export function EntityQuickCreate({ onCreate, onCancel }: { onCreate?: (entity: { name: string; type: 'supplier' | 'customer'; taxId?: string }) => void; onCancel?: () => void }) {
  const [name, setName] = React.useState('')
  const [type, setType] = React.useState<'supplier' | 'customer'>('supplier')
  const [taxId, setTaxId] = React.useState('')
  return (
    <form onSubmit={(event) => { event.preventDefault(); if (name.trim()) onCreate?.({ name: name.trim(), type, taxId: taxId || undefined }) }} className="border bg-card p-3">
      <div className="flex items-center"><h3 className="text-[11px] font-semibold">Create entity inline</h3><button type="button" onClick={onCancel} className="ml-auto text-[10px] text-muted-foreground hover:text-foreground">Cancel</button></div>
      <div className="mt-2 grid grid-cols-[1fr_104px] gap-2"><label><span className="text-[10px] text-muted-foreground">Legal or trading name</span><input required value={name} onChange={(event) => setName(event.target.value)} className="mt-1 h-row-dense w-full border px-2 text-[11px] outline-none focus:ring-1 focus:ring-ring" /></label><label><span className="text-[10px] text-muted-foreground">Type</span><select value={type} onChange={(event) => setType(event.target.value as typeof type)} className="mt-1 h-row-dense w-full border px-2 text-[11px]"><option value="supplier">Supplier</option><option value="customer">Customer</option></select></label></div>
      <label className="mt-2 block"><span className="text-[10px] text-muted-foreground">ABN / NZBN (optional)</span><input value={taxId} onChange={(event) => setTaxId(event.target.value)} className="financial-data mt-1 h-row-dense w-full border px-2 text-[11px] outline-none focus:ring-1 focus:ring-ring" /></label>
      <Button type="submit" size="compact" className="mt-3" disabled={!name.trim()}>Create and select</Button>
    </form>
  )
}
