import { Badge } from '@/components/ui/badge'

export function EvidenceAttachmentLink({ name, kind, verified, onOpen, onRemove }: { name: string; kind: string; verified?: boolean; onOpen?: () => void; onRemove?: () => void }) {
  return (
    <div className="flex h-row-standard items-center gap-2 border bg-card px-2 text-[11px]"><span aria-hidden className="text-muted-foreground">▧</span><button type="button" onClick={onOpen} className="min-w-0 flex-1 truncate text-left font-semibold text-financial-audit hover:underline">{name}</button><span className="financial-data text-[10px] text-muted-foreground">{kind}</span>{verified && <Badge tone="credit">Verified</Badge>}{onRemove && <button type="button" aria-label={`Remove ${name}`} onClick={onRemove} className="text-muted-foreground hover:text-financial-debit">×</button>}</div>
  )
}
