import { cn } from '@/lib/utils'

export interface GstBalances { salesTax: number; purchaseTax: number; net: number; currency?: string }

export function BalanceSummaryCards({ balances }: { balances: GstBalances }) {
  const formatter = new Intl.NumberFormat('en-AU', { style: 'currency', currency: balances.currency ?? 'AUD', minimumFractionDigits: 2 })
  const items = [
    ['GST on sales', balances.salesTax, 'Collected output tax'],
    ['GST on purchases', balances.purchaseTax, 'Claimable input tax'],
    [balances.net >= 0 ? 'Net payable' : 'Net refundable', Math.abs(balances.net), balances.net >= 0 ? 'Due to ATO' : 'Expected from ATO']
  ] as const
  return (
    <div className="grid grid-cols-1 border-l border-t bg-card sm:grid-cols-3">
      {items.map(([label, value, note], index) => <div key={label} className="min-h-[84px] border-b border-r p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.06em] text-muted-foreground">{label}</p><p className={cn('financial-data mt-2 text-lg font-semibold tracking-tight', index === 2 && (balances.net >= 0 ? 'text-financial-debit' : 'text-financial-credit'))}>{formatter.format(value)}</p><p className="mt-1 text-[10px] text-muted-foreground">{note}</p></div>)}
    </div>
  )
}
