import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'

export interface UnmatchedDocument {
  id: string
  fileName: string
  supplier?: string
  receivedAt: string
  amount?: number
  currency?: string
  ocrState: 'ready' | 'processing' | 'failed'
}

export function UnmatchedQueuePanel({ documents, selectedId, onSelect }: { documents: UnmatchedDocument[]; selectedId?: string; onSelect?: (document: UnmatchedDocument) => void }) {
  return (
    <section aria-label="Unmatched receipt queue" className="flex min-h-0 flex-col border bg-card">
      <header className="flex h-row-standard items-center border-b px-3"><div><h2 className="text-[12px] font-semibold">Unmatched receipts</h2><p className="text-[10px] text-muted-foreground">{documents.length} awaiting evidence links</p></div><Badge tone="suspense" className="ml-auto">{documents.length}</Badge></header>
      <div className="scrollbar-thin min-h-0 overflow-auto">
        {documents.map((document) => (
          <button key={document.id} type="button" onClick={() => onSelect?.(document)} className={cn('grid min-h-[52px] w-full grid-cols-[1fr_auto] items-center gap-3 border-b px-3 text-left outline-none hover:bg-muted/45 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring', selectedId === document.id && 'bg-info-muted/45')}>
            <div className="min-w-0"><p className="truncate text-[11px] font-semibold">{document.supplier ?? document.fileName}</p><p className="financial-data mt-0.5 truncate text-[10px] text-muted-foreground">{document.receivedAt} · {document.id}</p></div>
            <div className="text-right">{document.amount !== undefined && <p className="financial-data text-[11px] font-semibold">{document.currency} {document.amount.toFixed(2)}</p>}<Badge tone={document.ocrState === 'ready' ? 'audit' : document.ocrState === 'failed' ? 'debit' : 'suspense'} className="mt-0.5">{document.ocrState}</Badge></div>
          </button>
        ))}
      </div>
    </section>
  )
}
