'use client'

import * as React from 'react'

import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'

export interface FinancialAccount {
  code: string
  name: string
  group: 'Assets' | 'Liabilities' | 'Income' | 'Expenses' | 'Clearing'
  currency?: string
}

export interface AccountSelectorProps {
  accounts: FinancialAccount[]
  value?: string
  onValueChange?: (accountCode: string) => void
  onOpenChange?: (open: boolean) => void
  placeholder?: string
  disabled?: boolean
  className?: string
}

export function AccountSelector({ accounts, value, onValueChange, onOpenChange, placeholder = 'Select account', disabled, className }: AccountSelectorProps) {
  const [open, setOpen] = React.useState(false)
  const [query, setQuery] = React.useState('')
  const rootRef = React.useRef<HTMLDivElement>(null)
  const listboxId = React.useId()
  const selected = accounts.find((account) => account.code === value)
  const groups = [...new Set(accounts.map((account) => account.group))]
  const filtered = accounts.filter((account) => `${account.code} ${account.name} ${account.group}`.toLowerCase().includes(query.toLowerCase()))

  const updateOpen = (next: boolean) => { setOpen(next); onOpenChange?.(next); if (!next) setQuery('') }

  React.useEffect(() => {
    const onPointerDown = (event: PointerEvent) => {
      if (rootRef.current && !rootRef.current.contains(event.target as Node)) updateOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  })

  return (
    <div ref={rootRef} className={cn('relative', className)}>
      <button
        type="button"
        disabled={disabled}
        aria-haspopup="listbox"
        aria-controls={listboxId}
        aria-expanded={open}
        onClick={() => updateOpen(!open)}
        onKeyDown={(event) => { if (event.key === 'ArrowDown') { event.preventDefault(); updateOpen(true) } }}
        className="flex h-row-dense w-full items-center gap-2 rounded-[var(--spatial-radius-strict)] border bg-background px-2 text-left text-[11px] outline-none hover:bg-muted/35 focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50"
      >
        {selected ? <><span className="financial-data rounded-sm bg-muted px-1.5 py-0.5 font-semibold">{selected.code}</span><span className="min-w-0 flex-1 truncate">{selected.name}</span>{selected.currency && <span className="financial-data text-[10px] text-muted-foreground">{selected.currency}</span>}</> : <span className="text-muted-foreground">{placeholder}</span>}
        <span aria-hidden className="ml-auto text-[8px] text-muted-foreground">▼</span>
      </button>

      {open && (
        <div className="absolute left-0 right-0 top-9 z-40 border bg-popover shadow-floating">
          <div className="border-b p-1.5">
            <input autoFocus aria-label="Search chart of accounts" value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => { if (event.key === 'Escape') updateOpen(false) }} placeholder="Code, name or group…" className="h-7 w-full border bg-background px-2 text-[11px] outline-none focus:ring-1 focus:ring-inset focus:ring-ring" />
          </div>
          <div id={listboxId} role="listbox" aria-label="Chart of accounts" className="scrollbar-thin max-h-60 overflow-auto py-1">
            {groups.map((group) => {
              const groupAccounts = filtered.filter((account) => account.group === group)
              if (!groupAccounts.length) return null
              return (
                <div key={group} role="group" aria-label={group}>
                  <p className="px-2 py-1 text-[9px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">{group}</p>
                  {groupAccounts.map((account) => (
                    <button key={account.code} type="button" role="option" aria-selected={account.code === value} onClick={() => { onValueChange?.(account.code); updateOpen(false) }} className={cn('flex h-row-dense w-full items-center gap-2 px-2 text-left text-[11px] hover:bg-accent focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-ring', account.code === value && 'bg-accent')}>
                      <span className="financial-data w-10 text-muted-foreground">{account.code}</span><span className="min-w-0 flex-1 truncate">{account.name}</span>{account.currency && <Badge tone="neutral">{account.currency}</Badge>}
                    </button>
                  ))}
                </div>
              )
            })}
            {!filtered.length && <p className="px-3 py-6 text-center text-[11px] text-muted-foreground">No matching accounts</p>}
          </div>
        </div>
      )}
    </div>
  )
}
