import * as React from 'react'

export interface GstBreakdownSection { id: string; label: string; count: number; taxable: number; gst: number; children?: React.ReactNode }

const money = new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD', minimumFractionDigits: 2 })

export function BreakdownAccordion({ sections, onToggle }: { sections: GstBreakdownSection[]; onToggle?: (id: string, open: boolean) => void }) {
  return (
    <div className="border bg-card">
      {sections.map((section) => <details key={section.id} onToggle={(event) => onToggle?.(section.id, event.currentTarget.open)} className="group border-b last:border-b-0"><summary className="grid h-row-standard cursor-pointer list-none grid-cols-[1fr_80px_140px_130px_18px] items-center px-3 text-[11px] hover:bg-muted/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"><span className="font-semibold">{section.label}</span><span className="financial-data text-right text-muted-foreground">{section.count}</span><span className="financial-data text-right">{money.format(section.taxable)}</span><span className="financial-data text-right font-semibold">{money.format(section.gst)}</span><span aria-hidden className="text-right text-[8px] text-muted-foreground transition-transform group-open:rotate-180">▼</span></summary>{section.children && <div className="border-t bg-muted/20 p-3">{section.children}</div>}</details>)}
    </div>
  )
}
