'use client'

import * as React from 'react'

import { Badge } from '@/components/ui/badge'

export interface CsvColumnMapping {
  source: string
  target: string
  required?: boolean
}

const targetFields = ['Date', 'Description', 'Reference', 'Debit', 'Credit', 'Amount', 'Balance', 'Currency', 'Ignore']

export function ColumnMapper({ mappings, onMappingChange }: { mappings: CsvColumnMapping[]; onMappingChange?: (source: string, target: string) => void }) {
  return (
    <div className="border bg-card">
      <div className="grid h-row-dense grid-cols-[1fr_32px_1fr_90px] items-center border-b bg-muted px-2 text-[10px] font-semibold uppercase tracking-[0.06em] text-muted-foreground"><span>CSV header</span><span /><span>TigerERP field</span><span>Requirement</span></div>
      {mappings.map((mapping) => (
        <div key={mapping.source} className="grid min-h-row-standard grid-cols-[1fr_32px_1fr_90px] items-center border-b px-2 text-[11px] last:border-b-0">
          <span className="financial-data truncate">{mapping.source}</span><span aria-hidden className="text-center text-muted-foreground">→</span>
          <select value={mapping.target} onChange={(event) => onMappingChange?.(mapping.source, event.target.value)} aria-label={`Map ${mapping.source}`} className="h-row-dense border bg-background px-2 outline-none focus:ring-1 focus:ring-inset focus:ring-ring">{targetFields.map((field) => <option key={field}>{field}</option>)}</select>
          <span className="pl-2">{mapping.required ? <Badge tone="suspense">Required</Badge> : <span className="text-muted-foreground">Optional</span>}</span>
        </div>
      ))}
    </div>
  )
}
