'use client'

import { cn } from '@/lib/utils'

export interface TaxCodeOption { code: string; label: string; rate: string; jurisdiction?: string }

export function TaxCodeSelector({ options, value, onValueChange }: { options: TaxCodeOption[]; value?: string; onValueChange?: (code: string) => void }) {
  return (
    <div role="radiogroup" aria-label="Tax code" className="grid grid-cols-2 border-l border-t">
      {options.map((option) => (
        <button key={option.code} type="button" role="radio" aria-checked={value === option.code} onClick={() => onValueChange?.(option.code)} className={cn('grid min-h-row-standard grid-cols-[1fr_auto] items-center border-b border-r px-2 text-left outline-none hover:bg-muted/45 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring', value === option.code && 'bg-warning-muted/60')}>
          <span><span className="financial-data text-[10px] font-semibold">{option.code}</span><span className="ml-2 text-[11px]">{option.label}</span></span><span className="financial-data text-[10px] text-muted-foreground">{option.rate}</span>
        </button>
      ))}
    </div>
  )
}
