'use client'

import * as React from 'react'

import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export interface CsvUploadDropzoneProps {
  maxBytes?: number
  onFilesSelected?: (files: File[]) => void
  onRejected?: (reason: string) => void
  className?: string
}

export function CsvUploadDropzone({ maxBytes = 10 * 1024 * 1024, onFilesSelected, onRejected, className }: CsvUploadDropzoneProps) {
  const inputRef = React.useRef<HTMLInputElement>(null)
  const [dragging, setDragging] = React.useState(false)

  const validate = (incoming: FileList | File[]) => {
    const files = Array.from(incoming)
    const invalid = files.find((file) => !file.name.toLowerCase().endsWith('.csv') || file.size > maxBytes)
    if (invalid) {
      onRejected?.(!invalid.name.toLowerCase().endsWith('.csv') ? 'Only CSV statement files are accepted.' : `Files must be smaller than ${Math.round(maxBytes / 1024 / 1024)} MB.`)
      return
    }
    onFilesSelected?.(files)
  }

  return (
    <div
      onDragEnter={(event) => { event.preventDefault(); setDragging(true) }}
      onDragOver={(event) => event.preventDefault()}
      onDragLeave={(event) => { if (!event.currentTarget.contains(event.relatedTarget as Node)) setDragging(false) }}
      onDrop={(event) => { event.preventDefault(); setDragging(false); validate(event.dataTransfer.files) }}
      className={cn('grid min-h-36 place-items-center border border-dashed bg-card p-5 text-center transition-colors', dragging ? 'border-financial-audit bg-info-muted/45' : 'border-border', className)}
    >
      <div>
        <span aria-hidden className="mx-auto grid size-8 place-items-center rounded-sm bg-muted text-muted-foreground">⇧</span>
        <p className="mt-2 text-[12px] font-semibold">Drop a bank statement CSV</p>
        <p className="mt-1 text-[11px] text-muted-foreground">Headers are inspected locally before any import is created.</p>
        <Button type="button" size="compact" variant="outline" className="mt-3" onClick={() => inputRef.current?.click()}>Choose CSV</Button>
        <input ref={inputRef} type="file" accept=".csv,text/csv" multiple className="sr-only" onChange={(event) => event.target.files && validate(event.target.files)} aria-label="Choose bank statement CSV files" />
      </div>
    </div>
  )
}
