'use client'

export interface GstPeriod { id: string; label: string; dueDate: string; state: 'open' | 'draft' | 'ready' | 'lodged' }

export function PeriodPicker({ periods, value, onValueChange }: { periods: GstPeriod[]; value: string; onValueChange?: (id: string) => void }) {
  const selected = periods.find((period) => period.id === value)
  return (
    <label className="flex h-row-standard min-w-0 flex-1 items-center gap-2 border bg-background px-2 sm:min-w-[280px] sm:flex-none"><span className="text-[10px] font-semibold uppercase tracking-[0.06em] text-muted-foreground">GST period</span><select value={value} onChange={(event) => onValueChange?.(event.target.value)} className="h-row-dense min-w-0 flex-1 border-0 bg-transparent text-[11px] font-semibold outline-none">{periods.map((period) => <option key={period.id} value={period.id}>{period.label} · {period.state}</option>)}</select>{selected && <span className="financial-data text-[10px] text-muted-foreground">DUE {selected.dueDate}</span>}</label>
  )
}
