import { Badge } from '@/components/ui/badge'
import { DataTableBase, type DataTableColumn } from '@/components/ui/data-table-base'

export interface BankImportRun {
  id: string
  fileName: string
  account: string
  importedAt: string
  rows: number
  status: 'validated' | 'processing' | 'blocked'
  actor: string
}

const columns: DataTableColumn<BankImportRun>[] = [
  { id: 'file', header: 'Source file', accessor: 'fileName', width: '220px', sortable: true },
  { id: 'account', header: 'Bank account', accessor: 'account', width: '180px', sortable: true },
  { id: 'imported', header: 'Imported', accessor: 'importedAt', width: '132px', financial: true, sortable: true },
  { id: 'rows', header: 'Rows', accessor: 'rows', width: '74px', align: 'right', financial: true },
  { id: 'status', header: 'State', accessor: 'status', width: '110px', cell: (row) => <Badge tone={row.status === 'validated' ? 'credit' : row.status === 'blocked' ? 'debit' : 'audit'} indicator>{row.status}</Badge> },
  { id: 'actor', header: 'Imported by', accessor: 'actor', width: '150px' }
]

export function ImportHistoryList({ runs, onOpen }: { runs: BankImportRun[]; onOpen?: (run: BankImportRun) => void }) {
  return <DataTableBase caption="Bank statement import history" columns={columns} rows={runs} getRowId={(row) => row.id} initialSort={{ columnId: 'imported', direction: 'desc' }} onRowActivate={onOpen} />
}
