import { Badge } from '@/components/ui/badge'
import { DataTableBase, type DataTableColumn } from '@/components/ui/data-table-base'

export interface GstException { id: string; date: string; description: string; amount: number; reason: string; severity: 'blocking' | 'warning'; owner?: string }

const columns: DataTableColumn<GstException>[] = [
  { id: 'date', header: 'Date', accessor: 'date', width: '96px', financial: true, sortable: true },
  { id: 'description', header: 'Transaction', accessor: 'description', width: '190px' },
  { id: 'reason', header: 'Exception', accessor: 'reason', width: '230px' },
  { id: 'owner', header: 'Owner', width: '120px', cell: (row) => row.owner ?? 'Unassigned' },
  { id: 'severity', header: 'Impact', accessor: 'severity', width: '88px', cell: (row) => <Badge tone={row.severity === 'blocking' ? 'debit' : 'suspense'} indicator>{row.severity}</Badge> },
  { id: 'amount', header: 'Amount', accessor: 'amount', width: '108px', align: 'right', financial: true, cell: (row) => `$${row.amount.toFixed(2)}` }
]

export function ExceptionsTable({ exceptions, onOpen }: { exceptions: GstException[]; onOpen?: (exception: GstException) => void }) {
  return <DataTableBase caption="GST classification exceptions" columns={columns} rows={exceptions} getRowId={(row) => row.id} onRowActivate={onOpen} emptyMessage="No unclassified records — this period can proceed to review" />
}
