'use client'

import * as React from 'react'

export function ManualSearchBar({ value, onValueChange, onSubmit, resultCount }: { value: string; onValueChange?: (value: string) => void; onSubmit?: (value: string) => void; resultCount?: number }) {
  return (
    <form onSubmit={(event) => { event.preventDefault(); onSubmit?.(value) }} className="flex h-row-standard items-center gap-2 border bg-background px-2 focus-within:ring-1 focus-within:ring-ring">
      <span aria-hidden className="text-muted-foreground">⌕</span>
      <input value={value} onChange={(event) => onValueChange?.(event.target.value)} aria-label="Search transactions manually" placeholder="Reference, supplier, amount or date…" className="h-full min-w-0 flex-1 border-0 bg-transparent text-[11px] outline-none" />
      {resultCount !== undefined && <span className="financial-data text-[10px] text-muted-foreground">{resultCount} results</span>}
      <button type="submit" className="h-7 border px-2 text-[10px] font-semibold hover:bg-muted">Search</button>
    </form>
  )
}
