'use client'

import * as React from 'react'

import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export function DocumentDropzone({ onDocumentsSelected, onRejected, maxBytes = 20 * 1024 * 1024, className }: { onDocumentsSelected?: (files: File[]) => void; onRejected?: (reason: string) => void; maxBytes?: number; className?: string }) {
  const inputRef = React.useRef<HTMLInputElement>(null)
  const [active, setActive] = React.useState(false)
  const accept = (list: FileList | File[]) => {
    const files = Array.from(list)
    const hasInvalidType = files.some((file) => !['.pdf', '.jpg', '.jpeg', '.png', '.heic'].some((extension) => file.name.toLowerCase().endsWith(extension)))
    if (hasInvalidType) return onRejected?.('Receipts must be PDF, JPG, PNG or HEIC.')
    if (files.some((file) => file.size > maxBytes)) return onRejected?.(`Receipts must be smaller than ${Math.round(maxBytes / 1024 / 1024)} MB.`)
    onDocumentsSelected?.(files)
  }
  return (
    <div onDragOver={(event) => { event.preventDefault(); setActive(true) }} onDragLeave={() => setActive(false)} onDrop={(event) => { event.preventDefault(); setActive(false); accept(event.dataTransfer.files) }} className={cn('flex min-h-28 flex-wrap items-center gap-4 border border-dashed bg-card p-4', active && 'border-financial-audit bg-info-muted/40', className)}>
      <span aria-hidden className="grid size-10 shrink-0 place-items-center rounded-sm bg-muted text-lg text-muted-foreground">▧</span>
      <div className="min-w-[180px] flex-1"><p className="text-[12px] font-semibold">Add receipts and bills</p><p className="mt-1 text-[11px] text-muted-foreground">PDF, JPG, PNG or HEIC · up to {Math.round(maxBytes / 1024 / 1024)} MB · OCR starts after validation</p></div>
      <Button type="button" size="compact" variant="outline" onClick={() => inputRef.current?.click()}>Choose files</Button>
      <input ref={inputRef} type="file" multiple accept="application/pdf,image/jpeg,image/png,image/heic" className="sr-only" aria-label="Choose receipt documents" onChange={(event) => event.target.files && accept(event.target.files)} />
    </div>
  )
}
