import { DataTableBase, type DataTableColumn } from '@/components/ui/data-table-base'

export function DataPreviewGrid({ rows }: { rows: Array<Record<string, string>> }) {
  const headers = Object.keys(rows[0] ?? {})
  const columns: DataTableColumn<Record<string, string>>[] = headers.map((header) => ({ id: header, header, accessor: header, width: header.toLowerCase().includes('description') ? '260px' : '130px', financial: /date|amount|debit|credit|balance/i.test(header) }))
  return <DataTableBase caption="Mapped statement data preview" columns={columns} rows={rows} getRowId={(_, index) => String(index)} emptyMessage="Map columns to preview statement rows" />
}
