import { Badge } from '@/components/ui/badge'

export function OcrSuggestionBadge({ confidence }: { confidence: number }) {
  const tone = confidence >= 90 ? 'credit' : confidence >= 70 ? 'audit' : 'suspense'
  return <Badge tone={tone} indicator><span>OCR suggestion</span><span className="financial-data">{confidence}%</span></Badge>
}
