'use client'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { BalanceSummaryCards, type GstBalances } from './balance-summary-cards'
import { BreakdownAccordion, type GstBreakdownSection } from './breakdown-accordion'
import { ExceptionsTable, type GstException } from './exceptions-table'
import { PeriodPicker, type GstPeriod } from './period-picker'

export interface GstOverviewProps {
  periods: GstPeriod[]
  periodId: string
  balances: GstBalances
  sections: GstBreakdownSection[]
  exceptions: GstException[]
  onPeriodChange?: (periodId: string) => void
  onExceptionOpen?: (exception: GstException) => void
  onSubmitForReview?: () => void
}

export function GstOverview({ periods, periodId, balances, sections, exceptions, onPeriodChange, onExceptionOpen, onSubmitForReview }: GstOverviewProps) {
  const blockingCount = exceptions.filter((exception) => exception.severity === 'blocking').length
  const locked = exceptions.length > 0
  return (
    <section aria-label="GST period overview" className="flex min-h-0 flex-col bg-background">
      <header className="flex min-h-[52px] flex-wrap items-center gap-2 border bg-card p-2 sm:gap-3 sm:px-3"><div className="min-w-[220px] flex-1"><h1 className="text-[14px] font-semibold tracking-tight">GST period overview</h1><p className="text-[11px] text-muted-foreground">Projection as at cursor 9,420,181 · reconciled 2 minutes ago</p></div><PeriodPicker periods={periods} value={periodId} onValueChange={onPeriodChange} /><Button type="button" size="sm" disabled={locked} onClick={onSubmitForReview}>Submit for review</Button></header>
      {locked && <div role="alert" className="mt-2 flex min-h-row-standard flex-wrap items-center gap-2 border border-financial-debit/35 bg-card px-3 py-2 text-[11px]"><span aria-hidden className="size-1.5 bg-financial-debit" /><strong>Submission locked</strong><span className="min-w-[220px] flex-1 text-muted-foreground">Resolve every classification exception before this period can enter review.</span><Badge tone="debit">{blockingCount} blocking · {exceptions.length} total</Badge></div>}
      <div className="mt-2"><BalanceSummaryCards balances={balances} /></div>
      <div className="mt-2 grid min-h-0 flex-1 grid-cols-1 gap-2 2xl:grid-cols-[0.9fr_1.1fr]"><div className="min-w-0"><div className="flex h-row-standard items-center border border-b-0 bg-card px-3"><h2 className="text-[11px] font-semibold">Tax breakdown</h2><span className="ml-auto text-[10px] text-muted-foreground">Transactions · Taxable · GST</span></div><BreakdownAccordion sections={sections} /></div><div className="flex min-w-0 flex-col"><div className="flex h-row-standard items-center border border-b-0 bg-card px-3"><h2 className="text-[11px] font-semibold">Exceptions</h2><Badge tone={locked ? 'debit' : 'credit'} className="ml-auto">{exceptions.length}</Badge></div><ExceptionsTable exceptions={exceptions} onOpen={onExceptionOpen} /></div></div>
    </section>
  )
}
