'use client'

import * as React from 'react'

import { Badge } from '@/components/ui/badge'
import { DataTableBase, type DataTableColumn } from '@/components/ui/data-table-base'

export interface ClassificationRecord {
  id: string
  date: string
  description: string
  counterparty: string
  amount: number
  currency: string
  accountCode?: string
  taxCode?: string
  state: 'unclassified' | 'suggested' | 'reviewed'
  evidenceCount: number
}

export function FilterableReviewQueue({ records, onOpenRecord, onFilterChange }: { records: ClassificationRecord[]; onOpenRecord?: (record: ClassificationRecord) => void; onFilterChange?: (query: string, state: string) => void }) {
  const [query, setQuery] = React.useState('')
  const [state, setState] = React.useState('all')
  const filtered = records.filter((record) => (state === 'all' || record.state === state) && `${record.description} ${record.counterparty} ${record.id}`.toLowerCase().includes(query.toLowerCase()))
  const update = (nextQuery: string, nextState: string) => { setQuery(nextQuery); setState(nextState); onFilterChange?.(nextQuery, nextState) }

  const columns: DataTableColumn<ClassificationRecord>[] = [
    { id: 'date', header: 'Date', accessor: 'date', width: '108px', financial: true, sortable: true },
    { id: 'description', header: 'Transaction', accessor: 'description', width: '260px', sortable: true },
    { id: 'entity', header: 'Entity', accessor: 'counterparty', width: '180px', sortable: true },
    { id: 'amount', header: 'Amount', accessor: 'amount', width: '132px', align: 'right', financial: true, sortable: true, cell: (record) => `${record.currency} ${record.amount.toFixed(2)}` },
    { id: 'account', header: 'Account', width: '112px', financial: true, cell: (record) => record.accountCode ?? '—' },
    { id: 'tax', header: 'Tax', width: '100px', financial: true, cell: (record) => record.taxCode ?? '—' },
    { id: 'evidence', header: 'Evidence', width: '82px', align: 'center', financial: true, cell: (record) => record.evidenceCount },
    { id: 'state', header: 'Review state', accessor: 'state', width: '120px', cell: (record) => <Badge tone={record.state === 'reviewed' ? 'credit' : record.state === 'suggested' ? 'audit' : 'suspense'} indicator>{record.state}</Badge> }
  ]

  return (
    <section aria-label="Central classification workbench" className="flex min-h-0 flex-col border bg-card">
      <header className="flex min-h-row-standard flex-wrap items-center gap-2 border-b p-1 sm:px-2">
        <label className="flex h-row-dense min-w-[240px] flex-1 items-center gap-2 border bg-background px-2 focus-within:ring-1 focus-within:ring-ring"><span aria-hidden className="text-muted-foreground">⌕</span><span className="sr-only">Filter review queue</span><input value={query} onChange={(event) => update(event.target.value, state)} placeholder="Filter transactions…" className="h-full min-w-0 flex-1 border-0 bg-transparent text-[11px] outline-none" /></label>
        <select value={state} onChange={(event) => update(query, event.target.value)} aria-label="Filter by review state" className="h-row-dense border bg-background px-2 text-[11px] outline-none focus:ring-1 focus:ring-ring"><option value="all">All states</option><option value="unclassified">Unclassified</option><option value="suggested">Suggested</option><option value="reviewed">Reviewed</option></select>
        <span className="financial-data ml-auto text-[10px] text-muted-foreground">{filtered.length} / {records.length}</span>
      </header>
      <DataTableBase className="min-h-0 flex-1 border-0" caption="Classification review queue" columns={columns} rows={filtered} getRowId={(record) => record.id} onRowActivate={onOpenRecord} initialSort={{ columnId: 'date', direction: 'desc' }} />
    </section>
  )
}
