import { Button } from '@/components/ui/button'

export interface ImportValidationError {
  row?: number
  code: string
  message: string
}

export function ValidationErrorCallout({ errors, onDownloadReport }: { errors: ImportValidationError[]; onDownloadReport?: () => void }) {
  if (!errors.length) return null
  return (
    <div role="alert" className="border border-financial-debit/35 bg-card">
      <div className="flex h-row-standard items-center gap-2 border-b border-financial-debit/20 px-3"><span aria-hidden className="size-1.5 bg-financial-debit" /><p className="text-[12px] font-semibold">Import blocked · {errors.length} validation {errors.length === 1 ? 'error' : 'errors'}</p><Button type="button" size="compact" variant="outline" className="ml-auto" onClick={onDownloadReport}>Error report</Button></div>
      <ul className="divide-y">
        {errors.slice(0, 4).map((error) => <li key={`${error.row}-${error.code}`} className="grid min-h-row-dense grid-cols-[72px_92px_1fr] items-center px-3 text-[11px]"><span className="financial-data text-muted-foreground">{error.row ? `ROW ${error.row}` : 'FILE'}</span><span className="financial-data text-financial-debit">{error.code}</span><span>{error.message}</span></li>)}
      </ul>
    </div>
  )
}
